<?php
namespace App\Filament\Resources\BusinessResource\RelationManagers;
use Filament\Forms; use Filament\Forms\Form; use Filament\Resources\RelationManagers\RelationManager; use Filament\Tables; use Filament\Tables\Table;
class ReviewsRelationManager extends RelationManager { protected static string $relationship='reviews'; protected static ?string $title='Reviews'; public function form(Form $form): Form{return $form->schema([Forms\Components\Select::make('user_id')->relationship('user','name')->required(),Forms\Components\TextInput::make('rating')->numeric()->minValue(1)->maxValue(5)->required(),Forms\Components\Textarea::make('comment'),Forms\Components\Select::make('moderation_status')->options(['approved'=>'Approved','hidden'=>'Hidden','pending'=>'Pending'])->required()]);} public function table(Table $table): Table{return $table->columns([Tables\Columns\TextColumn::make('user.name')->label('User'),Tables\Columns\TextColumn::make('rating')->badge(),Tables\Columns\TextColumn::make('comment')->limit(80),Tables\Columns\TextColumn::make('moderation_status')->badge()])->actions([Tables\Actions\EditAction::make(),Tables\Actions\DeleteAction::make()->label('Soft delete')]);} }
